    entries = []
    for line in raw_lines:
        if line.startswith('{'):
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue
            action = ev.get("action")
            iso = ev.get("iso_timestamp", "")
            svc = ev.get("service", "-")
            if action == "LOCK":
                details = ev.get("reason", "")
                display = f"{iso} LOCK {details}" if details else f"{iso} LOCK"
            elif action == "UNLOCK":
                details = ""
                display = f"{iso} UNLOCK"
            elif action == "CONFIG_SET":
                details = f"{ev.get('key', '')}={ev.get('value', '')}"
                display = f"{iso} CONFIG_SET {details}"
            elif action == "CONFIG_DELETE":
                details = ev.get("key", "")
                display = f"{iso} CONFIG_DELETE {details}"
            elif action == "SCALE":
                details = f"{svc} from {ev.get('previous', '-')} to {ev.get('replicas', '-')} replicas"
                display = f"{iso} SCALE {details}"
            elif action == "HEALTH":
                details = f"{svc} {ev.get('previous_state', '-')} -> {ev.get('state', '-')}"
                display = f"{iso} HEALTH {details}"
            elif action == "QUOTA_SET":
                details = f"{ev.get('resource', '-')}={ev.get('limit', '-')}"
                display = f"{iso} QUOTA_SET {details}"
            elif action == "QUOTA_REMOVE":
                details = ev.get("resource", "-")
                display = f"{iso} QUOTA_REMOVE {details}"
            elif action == "CLONE":
                details = f"from {ev.get('source', '-')}"
                display = f"{iso} CLONE {details}"
