def cmd_audit(args):
    values, flags, positionals = parse_opts(args, {"--section"}, {"--json"})
    if len(positionals) != 1:
        fail("audit requires an environment")

    env = positionals[0]
    assert_env_exists(env)

    section = values.get("--section")
    valid_sections = {
        "deployment": "Deployment Summary",
        "replicas": "Replica Summary",
        "health": "Health Summary",
        "quotas": "Quota Status",
        "config": "Config Variables",
        "lock": "Lock Status",
        "activity": "Recent Activity",
    }
    if section is not None and section not in valid_sections:
        fail(f"unknown section '{section}' (valid: deployment, replicas, health, quotas, config, lock, activity)")
    if "--json" in flags and section is not None:
        fail("--json and --section cannot be combined")

    state = load_deployment_state(env)
    services = sorted(state)
    deployment = {}
    replicas = {}
    health = {}
    for s in services:
        rec = state[s]
        deployment[s] = {
            "version": rec.get("version", ""),
            "timestamp": rec.get("deployed_at", ""),
        }
        replicas[s] = get_replica_count(env, s)
        health[s] = get_health_state(env, s)

    quota_data = load_quotas(env)
    quotas = {}
    for resource in sorted(quota_data):
        limit = quota_data[resource]
        usage = quota_current_usage(env, resource)
        status = "OK" if usage <= limit else "EXCEEDED"
        quotas[resource] = {
            "limit": limit,
            "current": usage,
            "status": status,
        }

    config_keys = sorted(load_config(env).keys())
    lock = load_lock(env)
    activity = audit_event_entries(env)

    if "--json" in flags:
        report = {
            "environment": env,
            "deployment": deployment,
            "replicas": replicas,
            "health": health,
            "quotas": quotas,
            "config": config_keys,
            "lock": {
                "locked": lock is not None,
                "reason": lock.get("reason", "manual lock") if lock is not None else None,
            },
            "activity": [
                {
                    "timestamp": e["timestamp"],
                    "action": e["action"],
                    "details": e["details"],
                }
                for e in activity
            ],
        }
        print(json.dumps(report, separators=(",", ":"), sort_keys=True))
        return

    def deployment_lines():
        if not services:
            return ["  (no services deployed)"]
        return [
            f"  {s}: {deployment[s]['version']} (deployed {deployment[s]['timestamp']})"
            for s in services
        ]

    def replica_lines():
        if not services:
            return ["  (no services deployed)"]
        return [f"  {s}: {replicas[s]} replicas" for s in services]

    def health_lines():
        if not services:
            return ["  (no services deployed)"]
        return [f"  {s}: {health[s]}" for s in services]

    def quota_lines():
        if not quotas:
            return ["  (no quotas set)"]
        return [
            f"  {resource}: {quotas[resource]['limit']} (current: {quotas[resource]['current']}) [{quotas[resource]['status']}]"
            for resource in sorted(quotas)
        ]

    def config_lines():
        if not config_keys:
            return ["  (no config variables)"]
        return [f"  {key}" for key in config_keys]

    def lock_lines():
        if lock is not None:
            return [f"  Locked: {lock.get('reason', 'manual lock')}"]
        return ["  Unlocked"]

    def activity_lines():
        if not activity:
            return ["  (no events)"]
        return [f"  {e['display']}" for e in activity]

    section_order = ["deployment", "replicas", "health", "quotas", "config", "lock", "activity"]
    section_funcs = {
        "deployment": deployment_lines,
        "replicas": replica_lines,
        "health": health_lines,
        "quotas": quota_lines,
        "config": config_lines,
        "lock": lock_lines,
        "activity": activity_lines,
    }

    print(f"=== Audit Report: {env} ===")
    if section is not None:
        print(f"--- {valid_sections[section]} ---")
        for line in section_funcs[section]():
            print(line)
    else:
        for key in section_order:
            print(f"--- {valid_sections[key]} ---")
            for line in section_funcs[key]():
                print(line)
    print("=== End Audit Report ===")

'''
